mapper.select:
SELECT t.id, t.ticket_no, t.line_id, l.line_name, t.start_station_id, start_station.station_name AS start_station_name, t.end_station_id, end_station.station_name AS end_station_name, t.direction, t.travel_date, t.departure_time, t.arrival_time, t.price, t.total_stock, t.remaining_stock, t.status FROM tickets t INNER JOIN metro_lines l ON l.id = t.line_id INNER JOIN stations start_station ON start_station.id = t.start_station_id INNER JOIN stations end_station ON end_station.id = t.end_station_id WHERE t.status <> 'DRAFT'
AND t.start_station_id = #{startStationId}
AND t.end_station_id = #{endStationId}
AND t.travel_date = #{travelDate}
AND t.direction = #{direction}
ORDER BY t.travel_date ASC, t.departure_time ASC
